    #"Encabezados promovidos" = Table.PromoteHeaders(Origen, [PromoteAllScalars=true]),
    #"Tipo cambiado" = Table.TransformColumnTypes(#"Encabezados promovidos",{{"FECHA", type date}, {"# ORDEN", Int64.Type}, {"# BULTOS", Int64.Type}, {"TIIPO CAJA", type text}, {"# CONTENEDORA", Int64.Type}, {"VOLUMEN M3", Int64.Type}, {"", type text}, {"MES", Int64.Type}, {"AÑO", Int64.Type}, {"_1", type text}, {"TIPO CAJA", type text}, {"Largo", Int64.Type}, {"Ancho", Int64.Type}, {"Alto", Int64.Type}, {"VOLUMEN", Int64.Type}, {"PESO", Int64.Type}, {"_2", type text}, {"_3", type text}, {"_4", type text}, {"_5", type text}, {"_6", type text}, {"_7", type text}, {"_8", type text}, {"_9", type text}, {"_10", type text}, {"_11", type text}}),
    #"Columnas quitadas" = Table.RemoveColumns(#"Tipo cambiado",{"# BULTOS", "VOLUMEN M3", "", "MES", "AÑO", "_1", "TIPO CAJA", "Largo", "Ancho", "Alto", "VOLUMEN", "PESO", "_2", "_3", "_4", "_5", "_6", "_7", "_8", "_9", "_10", "_11"}),
